22: // Host formats a revision number to a downloadable URL for the browser.
23: type Host func(revision int) string
24: 
25: var hostConf = map[string]struct {
26: 	urlPrefix string
27: 	zipName   string
28: }{
29: 	"darwin_amd64":  {"Mac", "chrome-mac.zip"},
30: 	"darwin_arm64":  {"Mac_Arm", "chrome-mac.zip"},
31: 	"linux_amd64":   {"Linux_x64", "chrome-linux.zip"},
32: 	"windows_386":   {"Win", "chrome-win.zip"},
33: 	"windows_amd64": {"Win_x64", "chrome-win.zip"},
34: }[runtime.GOOS+"_"+runtime.GOARCH]
35: 
36: // HostGoogle to download browser.
37: func HostGoogle(revision int) string {
38: 	return fmt.Sprintf(
39: 		"https://storage.googleapis.com/chromium-browser-snapshots/%s/%d/%s",
40: 		hostConf.urlPrefix,
41: 		revision,
42: 		hostConf.zipName,
43: 	)
44: }
45: 
46: // HostNPM to download browser.
47: func HostNPM(revision int) string {
48: 	return fmt.Sprintf(
49: 		"https://registry.npmmirror.com/-/binary/chromium-browser-snapshots/%s/%d/%s",
50: 		hostConf.urlPrefix,
51: 		revision,
52: 		hostConf.zipName,
53: 	)
54: }
55: 
56: // HostPlaywright to download browser.
57: func HostPlaywright(revision int) string {
58: 	rev := RevisionPlaywright
59: 	if !(runtime.GOOS == "linux" && runtime.GOARCH == "arm64") {
60: 		rev = revision
61: 	}
62: 	return fmt.Sprintf(
63: 		"https://playwright.azureedge.net/builds/chromium/%d/chromium-linux-arm64.zip",
64: 		rev,
65: 	)
66: }
