68: // DefaultBrowserDir for downloaded browser. For unix is "$HOME/.cache/rod/browser",
69: // for Windows it's "%APPDATA%\rod\browser".
70: var DefaultBrowserDir = filepath.Join(map[string]string{
71: 	"windows": os.Getenv("APPDATA"),
72: 	"darwin":  filepath.Join(os.Getenv("HOME"), ".cache"),
