// Package rod is a high-level driver directly based on DevTools Protocol.
package rod

import (
	"context"
	"reflect"
	"strings"
	"sync"
	"time"

	"github.com/go-rod/rod/lib/cdp"
	"github.com/go-rod/rod/lib/defaults"
